package com.diberlog.jarvis.mobile;
import android.app.*;
import android.content.*;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import java.io.*;
import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class)
public class MindMapTests {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();
 JSONObject fixture()throws Exception{try(InputStream in=i.getContext().getAssets().open("desktop-mindmap-fixture.json")){return new JSONObject(PublicData.read(in,100000));}}
 MainActivity open(){return (MainActivity)i.startActivitySync(new Intent(i.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 @Test public void desktopFixtureAndSyncRetainMediaPlanAndPositions()throws Exception{JSONObject map=fixture();MindMapData.validate(map);JSONObject note=new JSONObject().put("id","map-fixture").put("title","Map").put("text","Portable").put("type","mindmap").put("mindMap",map).put("updatedAt",MobileStore.now());JSONObject base=MobileStore.empty().put("notes",new JSONArray().put(note)),remote=new JSONObject(base.toString());remote.getJSONArray("notes").getJSONObject(0).getJSONObject("mindMap").getJSONArray("nodes").getJSONObject(0).put("x",760);JSONObject result=MobileStore.merge(base,base,remote);MobileStore.validate(result);JSONObject retained=result.getJSONArray("notes").getJSONObject(0).getJSONObject("mindMap");assertEquals(760,retained.getJSONArray("nodes").getJSONObject(0).getInt("x"));assertEquals("YWJj",retained.getJSONArray("nodes").getJSONObject(0).getJSONArray("files").getJSONObject(0).getString("data"));assertEquals(1,retained.getJSONArray("nodes").getJSONObject(0).getJSONArray("images").length());assertTrue(retained.getJSONArray("nodes").getJSONObject(1).getJSONArray("items").getJSONObject(0).getBoolean("done"));}
 @Test public void rejectsMalformedGraphsAndExternalImages()throws Exception{JSONObject map=fixture();map.getJSONArray("edges").getJSONObject(0).put("to","missing");try{MindMapData.validate(map);fail();}catch(JSONException expected){}map=fixture();map.getJSONArray("nodes").getJSONObject(0).getJSONArray("images").getJSONObject(0).put("src","https://example.invalid/image");try{MindMapData.validate(map);fail();}catch(JSONException expected){}map=fixture();map.getJSONArray("nodes").getJSONObject(0).getJSONArray("files").getJSONObject(0).put("size",4);try{MindMapData.validate(map);fail();}catch(JSONException expected){}}
 @Test public void bundledEditorSavesMapAndReopensAfterRestart()throws Exception{
  MainActivity a=open();String id="mindmap-ui-"+java.util.UUID.randomUUID();try{
   JSONObject center=MobileStore.center(a);center.getJSONArray("notes").put(new JSONObject().put("id",id).put("title",id).put("text","Portable map").put("type","mindmap").put("mindMap",fixture()).put("updatedAt",MobileStore.now()));MobileStore.save(a,center);i.runOnMainSync(()->a.show(3));
   String select="(()=>{const b=[...document.querySelectorAll('.note-list button')].find(b=>b.textContent.includes('"+id+"'));if(!b)return false;b.click();return !!document.querySelector('.map-node');})()";
   assertTrue(PolishTests.waitJs(i,a,select));assertTrue(PolishTests.waitJs(i,a,"(()=>{const b=document.querySelector('.node-heading');if(!b)return false;b.click();return !!document.querySelector('[aria-label=\"Название карточки\"]');})()"));
   assertTrue(PolishTests.waitJs(i,a,"(()=>{const t=document.querySelector('[aria-label=\"Название карточки\"]');t.value='Изменено на телефоне';t.dispatchEvent(new Event('input',{bubbles:true}));document.querySelector('[aria-label=\"Закрыть карточку\"]').click();document.querySelector('.actions .primary').click();return true;})()"));
   boolean saved=false;for(int n=0;n<40;n++){JSONArray notes=MobileStore.center(a).getJSONArray("notes");for(int j=0;j<notes.length();j++)if(notes.getJSONObject(j).optString("id").equals(id))saved=notes.getJSONObject(j).getJSONObject("mindMap").getJSONArray("nodes").getJSONObject(0).getString("title").equals("Изменено на телефоне");if(saved)break;Thread.sleep(100);}assertTrue(saved);PolishTests.shot(i,a,"preview-mindmap-android.png");assertTrue(PolishTests.waitJs(i,a,"(()=>{if(!document.querySelector('.mind-map.expanded'))document.querySelector('[aria-label=\"Развернуть карту\"]').click();return !!document.querySelector('.mind-map.expanded');})()"));Thread.sleep(350);i.waitForIdleSync();PolishTests.shot(i,a,"preview-mindmap-android-full.png");i.runOnMainSync(a::finish);
   MainActivity restarted=open();try{i.runOnMainSync(()->restarted.show(3));assertTrue(PolishTests.waitJs(i,restarted,select));assertTrue(PolishTests.waitJs(i,restarted,"document.body.textContent.includes('Изменено на телефоне')"));}finally{i.runOnMainSync(restarted::finish);}
  }finally{JSONObject center=MobileStore.center(a);JSONArray list=center.getJSONArray("notes");for(int n=list.length()-1;n>=0;n--)if(list.getJSONObject(n).optString("id").equals(id))list.remove(n);MobileStore.save(a,center);i.runOnMainSync(a::finish);}
 }
 @Test public void nativeAttachmentReaderReturnsOriginalBytes()throws Exception{MainActivity a=open();android.net.Uri uri=null;try{i.runOnMainSync(()->a.show(3));assertTrue(PolishTests.waitJs(i,a,"(()=>{if(!document.querySelector('.notes-panel'))return false;window.addEventListener('jarvis-attachment',e=>window.mapFileResult=e.detail);return true;})()"));ContentValues values=new ContentValues();values.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,"fictional-map-plan.txt");values.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,"text/plain");uri=a.getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);assertNotNull(uri);try(OutputStream out=a.getContentResolver().openOutputStream(uri)){out.write(new byte[]{97,98,99});}android.net.Uri selected=uri;i.runOnMainSync(()->a.centerPage.attachmentResult(selected));assertTrue(PolishTests.waitJs(i,a,"window.mapFileResult?.file?.data==='YWJj'&&window.mapFileResult.file.size===3"));}finally{if(uri!=null)a.getContentResolver().delete(uri,null,null);i.runOnMainSync(a::finish);}}
}
